function speechLocale(code:string){const value=languageCode(code)||(code||'').trim().toLowerCase();const locales:Record<string,string>={en:'en-US',ta:'ta-IN',hi:'hi-IN',ml:'ml-IN',te:'te-IN',kn:'kn-IN',bn:'bn-IN',mr:'mr-IN',gu:'gu-IN',pa:'pa-IN',ur:'ur-IN',fr:'fr-FR',de:'de-DE',es:'es-ES',it:'it-IT',pt:'pt-BR',ru:'ru-RU',ja:'ja-JP',ko:'ko-KR','zh-cn':'zh-CN','zh-tw':'zh-TW',ar:'ar-SA',th:'th-TH',vi:'vi-VN',id:'id-ID',tr:'tr-TR',nl:'nl-NL',pl:'pl-PL',sv:'sv-SE',fi:'fi-FI'};return locales[value]||(/^[a-z]{2}(-[a-z]{2,4})?$/i.test(value)?value:'en-US')}
