function scriptLanguage(value:string,fallback:string){const fromMetadata=languageCode(fallback);if(/[\u0B80-\u0BFF]/u.test(value))return'ta';if(/[\u0900-\u097F]/u.test(value))return fromMetadata==='mr'?'mr':'hi';if(/[\u0A00-\u0A7F]/u.test(value))return'pa';if(/[\u0980-\u09FF]/u.test(value))return'bn';if(/[\u0D00-\u0D7F]/u.test(value))return'ml';if(/[\u0C00-\u0C7F]/u.test(value))return fromMetadata==='kn'?'kn':'te';if(/[\u0600-\u06FF]/u.test(value))return fromMetadata==='ur'?'ur':'ar';if(/[\u3040-\u30FF\u4E00-\u9FFF]/u.test(value))return fromMetadata==='ja'?'ja':fromMetadata==='ko'?'ko':fromMetadata.startsWith('zh')?fromMetadata:'ja';return fromMetadata||'en'}
