function speechUnits(value:string,maxLength=360,mode:VoiceMode='natural',rate=1):SpeechUnit[]{const paragraphs=value.replace(/\r/g,'').split(/\n\s*\n+/).map(part=>part.trim()).filter(Boolean);const source=paragraphs.length?paragraphs:[value.trim()];const units:SpeechUnit[]=[];source.forEach((paragraph,paragraphIndex)=>{const sentences=paragraph.split(/(?<=[.!?।！？…])\s+|\n+/u).map(part=>part.trim()).filter(Boolean);sentences.forEach((sentence,sentenceIndex)=>{const cue=narrationCue(sentence,mode,rate,`${sentences[sentenceIndex-1]||''} ${sentences[sentenceIndex+1]||''}`);if(cue.kind==='dialogue')cue.pitch=Math.round((cue.pitch+(sentenceIndex%2?-.03:.03))*100)/100;let remaining=sentence;while(remaining.length>maxLength){let cut=remaining.lastIndexOf(';',maxLength);if(cut<100)cut=remaining.lastIndexOf(',',maxLength);if(cut<100)cut=remaining.lastIndexOf(' ',maxLength);if(cut<100)cut=maxLength;const part=remaining.slice(0,cut+1).trim();if(part){const pause=/[,،，、;；]$/.test(part)?150:260;units.push({text:part,pause,cue:{...cue,pause}})}remaining=remaining.slice(cut+1).trim()}if(remaining){const pause=sentenceIndex===sentences.length-1?(paragraphIndex===source.length-1?cue.pause:Math.max(cue.pause,560)):cue.pause;units.push({text:remaining,pause,cue:{...cue,pause}})}})});return units.filter(unit=>!!unit.text&&/[\p{L}\p{N}]/u.test(unit.text))}
