useEffect(()=>{const term=query.trim();const requestId=++suggestionRequest.current;if(!user||term.length<2){setSearchSuggestions([]);setSuggestionLoading(false);return}let active=true;const timer=window.setTimeout(async()=>{setSuggestionLoading(true);try{const params=new URLSearchParams({q:term,language,page:'1'});const data=await api(`/books/search?${params}`);if(active&&requestId===suggestionRequest.current)setSearchSuggestions((data.results as Book[]).slice(0,6))}catch{if(active)setSearchSuggestions([])}finally{if(active)setSuggestionLoading(false)}},300);return()=>{active=false;window.clearTimeout(timer)}},[query,language,user?.id]);
async function checkAppUpdate(){setUpdateChecking(true);setUpdateMessage('');if(!Capacitor.isNativePlatform()){try{const registration=await navigator.serviceWorker.getRegistration();if(registration)await registration.update();setUpdateMessage('The web app checks for updates when it is reopened.')}catch{setUpdateMessage('Could not check for updates right now.')}finally{setUpdateChecking(false)}return}try{const status=await checkForNativeUpdate(API);setAppUpdateInfo(status.release);setAppUpdateAvailable(status.available);setUpdateMessage(status.available?`Version ${status.release.versionName} is ready to install.`:`its you is up to date (v${status.release.versionName}).`)}catch(error){setUpdateMessage((error as Error).message||'Could not check for updates. Connect to the laptop Wi-Fi and try again.')}finally{setUpdateChecking(false)}}
async function applyAppUpdate(){if(!appUpdateInfo)return;setUpdateMessage('Downloading the update…');try{const result=await installNativeUpdate(API,appUpdateInfo);setUpdateMessage(result.permissionRequired?'Allow its you to install unknown apps in Android settings, then return and tap Update now again.':'Download complete. Confirm Install in the Android installer to finish updating.')}catch(error){setUpdateMessage((error as Error).message||'Could not download the update. Connect to the laptop Wi-Fi and try again.')}}
